import{bV as t,aL as o,u as n,G as s}from"./chunks/framework.BidoRKjm.js";const c=JSON.parse('{"title":"简历","description":"","frontmatter":{"title":"简历","sidebar":false,"prev":false,"next":false,"comment":false,"articleUpdate":false},"headers":[],"relativePath":"devops-resume.md","filePath":"about/resume/devops-resume.md","lastUpdated":1788192834000}'),a={name:"devops-resume.md"};function e(l,r,i,g,h,u){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="简历" tabindex="-1">简历 <a class="header-anchor" href="#简历" aria-label="Permalink to &quot;简历&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>姓名</strong>：冯升刚</li><li><strong>年龄</strong>：20</li><li><strong>性别</strong>：男</li><li><strong>求职意向</strong>：DevOps工程师</li></ul><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ul><li><strong>操作系统</strong>：熟练掌握 <strong>Linux</strong> 常用命令，熟悉 <strong>Ubuntu</strong> 服务器日常维护</li><li><strong>容器化</strong>：熟练掌握容器化技术，如容器部署与编排，不同容器之间能够通信</li><li><strong>监控</strong>：了解 <strong>Prometheus</strong>、<strong>Grafana</strong> 等监控工具</li><li><strong>服务网关/代理</strong>：掌握 <strong>Nginx</strong> 反向代理，了解 <strong>Gunicorn</strong>、<strong>Uvicorn</strong> 和 <strong>Tomcat</strong></li><li><strong>组网</strong>：熟练使用 <strong>Tailscale</strong> 等虚拟局域网工具，能够独立完成虚拟局域网的搭建和维护</li><li><strong>自动化</strong>：熟练使用 <strong>Python</strong> 编写自动化脚本，完成日常运维任务、如缓存自动清理、数据库/容器定期备份、日志自动轮转删除等</li><li><strong>版本控制</strong>：熟练使用 Git，熟悉 GitHub Actions 流水线配置，实现主分支自动构建与部署</li><li><strong>数据库</strong>：熟练使用 <strong>SQL</strong> 基本操作，了解 <strong>PostgreSQL</strong> 备份恢复 操作逻辑，能够独立完成数据库维护任务</li></ul><h2 id="实战经历" tabindex="-1">实战经历 <a class="header-anchor" href="#实战经历" aria-label="Permalink to &quot;实战经历&quot;">​</a></h2><h3 id="个人私有云搭建与维护" tabindex="-1">个人私有云搭建与维护 <a class="header-anchor" href="#个人私有云搭建与维护" aria-label="Permalink to &quot;个人私有云搭建与维护&quot;">​</a></h3><p><strong>2026.6 — 至今</strong> | 个人项目 | 运维开发</p><h4 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h4><p>为构建统一的全栈开发环境与个人数据中心，利用闲置x86硬件资源，基于Linux和容器化技术搭建高可用私有云平台，旨在解决多环境依赖冲突及数据孤岛问题</p><h4 id="所用技术" tabindex="-1">所用技术 <a class="header-anchor" href="#所用技术" aria-label="Permalink to &quot;所用技术&quot;">​</a></h4><p>Python、Docker、Tailscale、Mise、1Panel、Crontab</p><h4 id="投入与成果" tabindex="-1">投入与成果 <a class="header-anchor" href="#投入与成果" aria-label="Permalink to &quot;投入与成果&quot;">​</a></h4><ul><li><strong>容器部署与编排</strong>：基于 <strong>Docker Compose</strong> 编排 20+ 容器（含数据库及可视化工具、网络磁盘映射器、密码库、流媒体、无头浏览器、监控等）按需启停，实现个人全栈开发环境集中管理</li><li><strong>多版本运行时环境构建</strong>：引入 <strong>Mise</strong> 统一管理 <strong>Java/Python/GO/Node</strong> 等多语言运行时、<strong>pnpm/uv</strong>包管理器，通过配置文件实现项目级环境隔离与自动激活，彻底解决本地开发环境的依赖冲突痛点</li><li><strong>可视化运维</strong>：部署 <strong>1Panel</strong> 现代化运维面板，集成系统监控与日志审计功能，将复杂的命令行操作图形化，提升日常巡检与故障排查效率</li><li><strong>异地组网</strong>：基于 <strong>Tailscale</strong> 组建异地虚拟局域网，确保服务在异地可访问，保障数据安全与传输隐私</li><li><strong>资源节省</strong>：利用 BIOS设置配合智能插座 实现服务器按需启动</li><li><strong>智能关机</strong>：独立开发 <strong>Python 守护进程</strong>，多维度采集 CPU/IO/网络负载指标；设计误关机策略结合 <strong>Crontab</strong> 定时轮询，实现无人值守时的自动休眠，实测降低长期运行功耗约 70%</li><li><strong>自动化</strong>：编写 <strong>Python 脚本</strong>，实现缓存自动清理、数据库/容器定期备份、日志自动轮转删除，将日常运维工作量降低约 80%</li></ul><h3 id="个人站点搭建与维护" tabindex="-1">个人站点搭建与维护 <a class="header-anchor" href="#个人站点搭建与维护" aria-label="Permalink to &quot;个人站点搭建与维护&quot;">​</a></h3><p><strong>2026.8 — 至今</strong> | 个人项目 | 运维开发</p><ul><li><strong>站点搭建</strong>：基于 <strong>Vitepress</strong> 和 <strong>Teek</strong> 搭建文档+博客双风格 的静态站点，采用 <strong>Markdown文档</strong>驱动内容生产，大幅缩短文档排版</li><li><strong>优化更新流程</strong>：利用 已部署的 <strong>webdav容器</strong> 将服务器存储映射为本地磁盘，配合本地编辑器实现“本地编辑、云端实时同步”的无感发布体验，优化内容管理流程</li><li><strong>自动化部署</strong>：使用 <strong>Github Actions</strong> 实现自动化部署，确保网站在代码仓库更新后自动部署</li><li><strong>多平台部署</strong>：采用 <strong>Github Pages/Cloudflare Pages</strong> 双平台部署策略，利用 <strong>CDN</strong> 加速全球访问，确保站点的高可用性与低延迟</li></ul><h2 id="教育背景" tabindex="-1">教育背景 <a class="header-anchor" href="#教育背景" aria-label="Permalink to &quot;教育背景&quot;">​</a></h2><ul><li><strong>学校</strong>：江西省工业贸易职业技术学院</li><li><strong>年份</strong>：2024.9 — 2027.6</li><li><strong>专业</strong>：软件技术</li></ul><h2 id="获奖经历" tabindex="-1">获奖经历 <a class="header-anchor" href="#获奖经历" aria-label="Permalink to &quot;获奖经历&quot;">​</a></h2><ul><li>🥇 <strong>江西省职业院校技能大赛</strong> — 金奖</li><li>🥈 <strong>一带一路暨金砖国家技能发展与技术创新大赛</strong> — 银奖</li><li>🥈 <strong>大学生创新创业大赛</strong> — 银奖</li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><ul><li><strong>GitHub</strong>：<a href="https://github.com/mobei-front" target="_blank" rel="noreferrer">mobei-front</a></li><li><strong>邮箱</strong>：<a href="mailto:2811218461@qq.com" target="_blank" rel="noreferrer">2811218461@qq.com</a></li></ul>',23)])])}const b=t(a,[["render",e]]);export{c as __pageData,b as default};
